// Function to send the event to Google Analytics
function sendTrackEvent(category, action, label) {
  if (window.ga) {
    ga('send', 'event', category, action, label);
  }
  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({
    event: category,
    click_section: action,
    click_link: label,
  });
  return;
}

document.addEventListener('click', function (event) {
  const trackElement = event.target.closest('.js-ciHeader-track');
  const autoCompleteClick = event.target.closest('#autocomplete');
  const ttarpElement = event.target.closest('.ciHeader .ciHeader-phoneNumberLink');
  const chatElement = event.target.closest('.ciHeader .ghf-customerChat--default .sb-LiveEngage-chat');

  if (autoCompleteClick) {
    window.dataLayer.push({
      event: 'meganav',
      click_section: 'search',
    });
  }
  if (trackElement) {
    const action = trackElement.getAttribute('data-section') || 'Undefined';
    const label = trackElement.getAttribute('data-link') || 'Undefined';
    const category = trackElement.getAttribute('data-category') || 'meganav';
    sendTrackEvent(category, action, label);
  }
  if (ttarpElement) {
    sendTrackEvent('meganav','ttarp','ttarp link');
  }
  if (chatElement) {
    sendTrackEvent('meganav','chat','chat link');
  }
});

const getCookieValue = cookieName => {
  const cookies = document.cookie.split(';').map(cookie => cookie.trim());
  const foundCookie = cookies.find(cookie => cookie.startsWith(`${cookieName}=`));
  if (foundCookie) {
    const [, cookieValue] = foundCookie.split('=');
    return cookieValue;
  }
  return null;
};

// Combined window load event listener
window.addEventListener('load', function () {

  // TTARP Test
  const ttarpTestCookie = getCookieValue('feature_ttarp_test_v2');
  window.dataLayer.push({
    event: 'ab_test_group',
    ab_test_name: '2024 09 25 ttarp number',
    ab_test_location: 'header',
    ab_test_group: ttarpTestCookie,
  });
});

// Function to handle phone number replacements
function handlePhoneNumberReplacements() {
  const PHONE_NUMBER_OG = "800-293-4232";
  const PHONE_NUMBER_CONTROL = "855-256-1652";
  const PHONE_NUMBER_TEST = "855-271-2660";
  const PHONE_NUMBER_CONTROL_HVPR = "844-221-2538";
  const PHONE_NUMBER_TEST_HVPR = "844-222-8343";
  const FUNDRAISING_DONT_REPLACE = "855-845-3008";

  function replaceElements(TO_REPLACE, PHONE_NUMBER, PHONE_NUMBER_HVPR) {
    const links = document.querySelectorAll(
      `a[data-js="ttarp-overrideable"][href="tel:${TO_REPLACE}"]`
    );
    links.forEach((link) => {
      link.setAttribute('href', `tel:${PHONE_NUMBER}`);
    });
    const spans = document.querySelectorAll('span[data-js="ttarp-overrideable"]');
    spans.forEach((span) => {
      if (span.textContent.trim() === TO_REPLACE) {
        span.textContent = PHONE_NUMBER;
      }
    });
    const cookieName = "ttarp_override";
    const cookies = document.cookie.split(';');
    let overrideValue = null;
    for (let i = 0; i < cookies.length; i++) {
      const cookie = cookies[i].trim();
      if (cookie.indexOf(cookieName) === 0) {
        overrideValue = cookie.substring(cookieName.length + 1);
        break;
      }
    }
    if (overrideValue === '855-792-1402') {
      const allOverrideableElements = document.querySelectorAll('[data-js="ttarp-overrideable"]');
      allOverrideableElements.forEach(element => {
        if (element.tagName.toLowerCase() === 'a' && element.getAttribute('href') !== `tel:${FUNDRAISING_DONT_REPLACE}`) {
          element.setAttribute('href', `tel:${PHONE_NUMBER_HVPR}`);
        } else if (element.tagName.toLowerCase() === 'span' && element.textContent.trim() !== `${FUNDRAISING_DONT_REPLACE}`) {
          element.textContent = PHONE_NUMBER_HVPR;
        }
      });
    };
  }

  // Delay to ensure the DOM is fully loaded and cookie values are processed
  setTimeout(() => {
    const ttarpCookieValue = getCookieValue('feature_ttarp_test_v2');
    if (ttarpCookieValue === 'test') {
      replaceElements(PHONE_NUMBER_OG, PHONE_NUMBER_TEST, PHONE_NUMBER_TEST_HVPR);
    } else if (ttarpCookieValue === 'control') {
      replaceElements(PHONE_NUMBER_OG, PHONE_NUMBER_CONTROL, PHONE_NUMBER_CONTROL_HVPR);
    }
  }, 500);
}

// Adding event listener for window load
window.addEventListener('load', handlePhoneNumberReplacements);
// Document ready event for DOMContentLoaded
document.addEventListener('DOMContentLoaded', handlePhoneNumberReplacements);
